app.get('/accounts/:accountId/statements/:id', requireLogin, async (req, res) => {
  const account = await db.accounts.find({ id: req.params.accountId, ownerId: req.user.id });
  if (!account) return res.sendStatus(404);
  const stmt = await db.statements.findById(req.params.id);
  res.json(stmt);
});

